## Protobuf's well-known types (google/protobuf/*.proto), generated into this
## package, plus conversions:
##
## * `Timestamp` <-> `times.Time`, `Duration` (protobuf) <-> `times.Duration`
## * `Any`: `pack`, `unpack`, `isA`
## * `Struct` / `Value` / `ListValue` <-> `JsonNode`
##
## Code generated by protoc-gen-nim imports these modules for any
## google/protobuf/*.proto dependency; nothing needs generating for them.
##
## `Duration` here is the protobuf message; `times.Duration` is Nim's. Where
## both are imported, qualify one: `duration_pb.Duration`.

import std/[times, json, tables, options, strutils, math]
import ./protobuf
import ./wkt/google/protobuf/[any_pb, duration_pb, empty_pb, field_mask_pb,
                              struct_pb, timestamp_pb, wrappers_pb]
export any_pb, duration_pb, empty_pb, field_mask_pb, struct_pb, timestamp_pb,
       wrappers_pb, protobuf

const
  minTimestampSeconds = -62135596800'i64   ## 0001-01-01T00:00:00Z
  maxTimestampSeconds = 253402300799'i64   ## 9999-12-31T23:59:59Z
  maxDurationSeconds = 315576000000'i64    ## 10000 years

# ---------------------------------------------------------------- Timestamp

proc toTimestamp*(t: Time): Timestamp =
  Timestamp(seconds: t.toUnix, nanos: t.nanosecond.int32)

proc toTime*(ts: Timestamp): Time =
  ## Raises ValueError outside the range protobuf allows (years 1..9999,
  ## nanos 0..999,999,999).
  if ts.seconds < minTimestampSeconds or ts.seconds > maxTimestampSeconds:
    raise newException(ValueError, "Timestamp seconds out of range: " & $ts.seconds)
  if ts.nanos < 0 or ts.nanos > 999_999_999:
    raise newException(ValueError, "Timestamp nanos out of range: " & $ts.nanos)
  initTime(ts.seconds, ts.nanos)

proc now*(_: typedesc[Timestamp]): Timestamp = getTime().toTimestamp

# ---------------------------------------------------------------- Duration

proc toProtoDuration*(d: times.Duration): duration_pb.Duration =
  ## Seconds and nanos carry the same sign, as protobuf requires.
  let ns = d.inNanoseconds
  duration_pb.Duration(seconds: ns div 1_000_000_000,
                       nanos: int32(ns mod 1_000_000_000))

proc toDuration*(d: duration_pb.Duration): times.Duration =
  ## Raises ValueError for values protobuf does not allow.
  if abs(d.seconds) > maxDurationSeconds:
    raise newException(ValueError, "Duration seconds out of range: " & $d.seconds)
  if abs(d.nanos) > 999_999_999 or (d.seconds > 0 and d.nanos < 0) or
     (d.seconds < 0 and d.nanos > 0):
    raise newException(ValueError, "Duration nanos invalid: " & $d.nanos)
  initDuration(seconds = d.seconds, nanoseconds = d.nanos)

# ---------------------------------------------------------------- Any

const typeUrlPrefix* = "type.googleapis.com/"

proc pack*[T](m: T): Any =
  ## Wraps `m` with the type URL "type.googleapis.com/<package>.<Message>".
  mixin encode, protoName
  Any(typeUrl: typeUrlPrefix & protoName(T), value: encode(m))

proc isA*[T](a: Any): bool =
  ## Whether `a` holds a `T` (the part of the type URL after its last '/').
  mixin protoName
  let i = a.typeUrl.rfind('/')
  a.typeUrl[i + 1 .. ^1] == protoName(T)

proc unpack*[T](a: Any): T =
  ## Raises ProtobufError if `a` holds another type or does not decode.
  mixin decode, protoName
  if not isA[T](a):
    raise newException(ProtobufError, "Any holds " & a.typeUrl & ", not " & protoName(T))
  decode(T, a.value)

# ---------------------------------------------------------------- Struct <-> JSON

proc toJson*(v: Value): JsonNode
proc toJson*(s: Struct): JsonNode =
  result = newJObject()
  for k, v in s.fields: result[k] = v.toJson

proc toJson*(l: ListValue): JsonNode =
  result = newJArray()
  for v in l.values: result.add v.toJson

proc toJson*(v: Value): JsonNode =
  ## An unset Value becomes null, like a null_value.
  if v.numberValue.isSome: newJFloat(v.numberValue.get)
  elif v.stringValue.isSome: newJString(v.stringValue.get)
  elif v.boolValue.isSome: newJBool(v.boolValue.get)
  elif v.hasStructValue: v.structValue.toJson
  elif v.hasListValue: v.listValue.toJson
  else: newJNull()

proc toValue*(j: JsonNode): Value
proc toStruct*(j: JsonNode): Struct =
  ## Raises ValueError unless `j` is a JSON object.
  if j.kind != JObject: raise newException(ValueError, "not a JSON object")
  for k, v in j: result.fields[k] = v.toValue

proc toValue*(j: JsonNode): Value =
  ## JSON numbers become doubles, as in protobuf's JSON mapping.
  case j.kind
  of JNull: Value(nullValue: some(NullValue_NULL_VALUE))
  of JBool: Value(boolValue: some(j.bval))
  of JInt: Value(numberValue: some(j.num.float64))
  of JFloat: Value(numberValue: some(j.fnum))
  of JString: Value(stringValue: some(j.str))
  of JObject: Value(structValue: j.toStruct, hasStructValue: true)
  of JArray:
    var l: ListValue
    for e in j: l.values.add e.toValue
    Value(listValue: l, hasListValue: true)
